page_settings.custom_css:
/* ===== AB Closets single post template ===== */
.abc-hero,.abc-body,.abc-helpers{--abc-navy:#0446A4;--abc-green:#198C51;--abc-text:#373737;--abc-heading:#1E2633;--abc-muted:#5F6672;--abc-line:#E3E6EB;font-family:Roboto,Arial,sans-serif}

/* Spacing comes from container gaps, not Elementor's default 20px under each widget */
.abc-hero .elementor-widget:not(:last-child),.abc-body .elementor-widget:not(:last-child){margin-block-end:0}
.abc-by p{margin:0}

/* Hero: compact split, title on solid background (never over the photo) */
.e-con.abc-hero{--content-width:1200px;--padding-top:48px;--padding-bottom:48px;--padding-left:24px;--padding-right:24px;--gap:48px;--row-gap:48px;--column-gap:48px;--align-items:center;background:#F5F5F5;border-bottom:1px solid #E3E6EB}
.e-con.abc-hero-text{--width:58%;--gap:14px;--row-gap:14px;--column-gap:14px;--padding-top:0;--padding-bottom:0;--padding-left:0;--padding-right:0}
.abc-hero-img{width:42%;flex:none}
.abc-hero-img img{width:100%;aspect-ratio:3/2;max-height:310px;object-fit:cover;border-radius:6px;box-shadow:0 10px 30px rgba(30,38,51,.12);display:block}
.abc-crumbs,.abc-crumbs a{font-size:13px;color:#5F6672;text-decoration:none}
.abc-crumbs a:hover{text-decoration:underline}
.abc-crumbs:empty{display:none}
.abc-title .elementor-heading-title{font-family:Roboto,Arial,sans-serif;font-size:40px;line-height:1.18;font-weight:700;color:#1E2633;letter-spacing:-.01em;text-wrap:balance;margin:0}
/* Colon rule: the part after ":" always starts on its own line (spans added by title-colon-break.php) */
.abc-title .title-main,.abc-title .title-sub{display:block;text-wrap:balance}
.abc-dek,.abc-dek p{font-size:18px;line-height:1.6;color:#5F6672;margin:0}
.e-con.abc-byline-row{--gap:16px;--row-gap:16px;--column-gap:16px;--align-items:center;--justify-content:space-between;--flex-wrap:wrap;--padding-top:4px;--padding-bottom:0;--padding-left:0;--padding-right:0}
.e-con.abc-byline{--gap:12px;--row-gap:12px;--column-gap:12px;--align-items:center;--width:auto;--padding-top:0;--padding-bottom:0;--padding-left:0;--padding-right:0}
.e-con.abc-byline-text{--gap:0;--row-gap:0px;--column-gap:0px;--width:auto;--padding-top:0;--padding-bottom:0;--padding-left:0;--padding-right:0}
.abc-avatar img{width:44px;height:44px;border-radius:50%;object-fit:cover;display:block}
.abc-by p,.abc-updated .elementor-heading-title{margin:0;font-size:14px;line-height:1.5;color:#5F6672;font-weight:400;font-family:Roboto,Arial,sans-serif}
.abc-by strong{color:#1E2633}

/* Share buttons */
.abc-share .elementor-share-btn{width:36px;height:36px;border-radius:50%}
.abc-share .elementor-grid{--grid-column-gap:8px;--grid-row-gap:8px}

/* Progress bar fixed to the top of the window */
.abc-progress{position:fixed!important;top:0;left:0;right:0;width:100%!important;z-index:9999;margin:0!important;pointer-events:none}
.abc-progress .elementor-scrolling-tracker{border-radius:0}

/* Body layout */
.e-con.abc-body{--content-width:1200px;--padding-top:44px;--padding-bottom:64px;--padding-left:24px;--padding-right:24px;--gap:56px;--row-gap:56px;--column-gap:56px;--align-items:flex-start}
.e-con.abc-article{--width:auto;flex:1 1 0;min-width:0;max-width:740px;--gap:0;--row-gap:0px;--column-gap:0px;--padding-top:0;--padding-bottom:0;--padding-left:0;--padding-right:0}
.e-con.abc-sidebar{--width:340px;flex:none;--gap:24px;--row-gap:24px;--column-gap:24px;--padding-top:0;--padding-bottom:0;--padding-left:0;--padding-right:0;align-self:stretch}
.e-con.abc-sticky{position:sticky;top:110px;--gap:24px;--row-gap:24px;--column-gap:24px;--padding-top:0;--padding-bottom:0;--padding-left:0;--padding-right:0}

/* Article typography */
.abc-content{font-size:17px;line-height:1.7;color:#373737}
.abc-content h2{font-size:28px;line-height:1.25;color:#1E2633;margin:44px 0 14px;scroll-margin-top:110px;font-weight:700}
.abc-content h3{font-size:20px;color:#1E2633;margin:28px 0 8px;font-weight:700}
.abc-content p{margin:0 0 18px}
.abc-content a{color:#0446A4}
.abc-content img{border-radius:6px;height:auto}
.abc-content figure.wp-block-table{overflow-x:auto;border:0;border-radius:10px;margin:28px 0 30px;box-shadow:0 6px 24px rgba(30,38,51,.08);background:#fff}
.abc-content .wp-block-table table{border:0;border-collapse:separate;border-spacing:0;width:100%;min-width:560px;font-size:15px;line-height:1.5}
.abc-content .wp-block-table td,.abc-content .wp-block-table th{border:0;border-bottom:1px solid #E3E6EB;padding:14px 18px;vertical-align:top;text-align:left}
.abc-content .wp-block-table tr:first-child td,.abc-content .wp-block-table th{background:#0446A4;color:#fff;font-weight:600;border-bottom:0;padding-top:15px;padding-bottom:15px}
.abc-content .wp-block-table tr:first-child td strong{color:#fff;font-weight:600}
.abc-content .wp-block-table tr:nth-child(odd):not(:first-child) td{background:#F7F9FC}
.abc-content .wp-block-table tr:not(:first-child):hover td{background:#EEF3FB}
.abc-content .wp-block-table tr:not(:first-child) td:first-child{font-weight:600;color:#1E2633}
.abc-content .wp-block-table tr:last-child td{border-bottom:0}
/* Article images: full column width with a soft shadow */
.abc-content figure.wp-block-image{margin:28px 0 30px;max-width:100%}
.abc-content .wp-block-image img,.abc-content p > img{width:100%!important;max-width:100%!important;height:auto!important;border-radius:10px;box-shadow:0 12px 32px rgba(30,38,51,.18);display:block}
.abc-content figure.wp-block-image figcaption{font-size:13px;color:#5F6672;text-align:center;margin-top:10px}

/* Table of contents */
.abc-toc-side,.abc-toc-inline{--box-border-color:#E3E6EB;--box-border-radius:6px;--box-padding:18px 20px;--header-color:#5F6672;--item-text-color:#373737;--item-text-hover-color:#0446A4;--item-text-active-color:#0446A4;--marker-color:#198C51}
.abc-toc-side .elementor-toc__header-title{font-size:13px;letter-spacing:.08em;text-transform:uppercase;color:#5F6672;font-weight:700}
.abc-toc-side .elementor-toc__list-item-text{font-size:14px;line-height:1.4}
.abc-toc-side .elementor-toc__body{max-height:52vh;overflow:auto;scrollbar-width:thin;scrollbar-color:#C9CED6 transparent}
.abc-toc-side .elementor-item-active{font-weight:500}
.abc-toc-inline{margin-bottom:28px}
.abc-toc-inline .elementor-toc__header-title{font-size:16px;color:#1E2633;font-weight:700}

/* Sidebar contact form */
.e-con.abc-form-box{--gap:0;--row-gap:0px;--column-gap:0px;--padding-top:0;--padding-bottom:0;--padding-left:0;--padding-right:0;border:1px solid #E3E6EB;border-radius:6px;overflow:hidden;background:#fff}
.e-con.abc-form-hd{background:#198C51;--padding-top:18px;--padding-bottom:18px;--padding-left:22px;--padding-right:22px;--gap:4px;--row-gap:4px;--column-gap:4px}
.abc-form-title .elementor-heading-title{color:#fff;font-size:20px;line-height:1.3;font-weight:700;margin:0;font-family:Roboto,Arial,sans-serif}
.abc-form-sub p{color:#fff;opacity:.92;font-size:14px;line-height:1.45;margin:0}
.abc-form{padding:18px 22px 8px}
.abc-form .wpcf7-form p{margin:0 0 12px}
.abc-form input:not([type=submit]):not([type=hidden]),.abc-form textarea{width:100%;font:inherit;font-size:15px;border:1px solid #C9CED6;border-radius:4px;padding:10px 12px;color:#373737;background:#fff;box-sizing:border-box}
.abc-form textarea{min-height:90px;max-height:160px;resize:vertical}
.abc-form input[type=submit]{width:100%;background:#0446A4;color:#fff;border:0;border-radius:4px;padding:12px 20px;font-size:15px;font-weight:500;cursor:pointer}
.abc-form input[type=submit]:hover{background:#03357D}
.abc-form-call{padding:0 22px 18px;text-align:center}
.abc-form-call p{margin:0;font-size:14px;color:#5F6672}
.abc-form-call a{font-weight:700;color:#1E2633;text-decoration:none;font-size:16px}

/* Trust points */
.abc-trust{border:1px solid #E3E6EB;border-radius:6px;padding:18px 20px;background:#fff}
.abc-trust .elementor-icon-list-text{font-size:14px;line-height:1.4;color:#373737}
.abc-trust .elementor-icon-list-item{align-items:flex-start;padding-bottom:10px}

/* Share row at the end */
.e-con.abc-share-end{--gap:16px;--row-gap:16px;--column-gap:16px;--align-items:center;--justify-content:space-between;--flex-wrap:wrap;border-top:1px solid #E3E6EB;border-bottom:1px solid #E3E6EB;--padding-top:16px;--padding-bottom:16px;--padding-left:0;--padding-right:0;margin:40px 0 32px}
.abc-share-label .elementor-heading-title{font-size:14px;color:#5F6672;margin:0;font-weight:400;font-family:Roboto,Arial,sans-serif}

/* Author box (same text as the previous theme author box) */
.e-con.abc-author{border:1px solid #E3E6EB;border-left:4px solid #198C51;border-radius:10px;--padding-top:28px;--padding-bottom:28px;--padding-left:28px;--padding-right:28px;--gap:24px;--row-gap:24px;--column-gap:24px;--align-items:flex-start;background:#fff;box-shadow:0 6px 24px rgba(30,38,51,.06)}
.abc-author-photo{flex:none;width:104px}
.abc-author-photo img{width:104px;height:104px;border-radius:50%;object-fit:cover;box-shadow:0 4px 14px rgba(30,38,51,.18);border:3px solid #fff;display:block}
.abc-author-text{flex:1 1 0;min-width:0;font-size:15px;line-height:1.7;color:#373737}
.abc-author-text p{margin:0 0 14px}
.abc-author-text .abc-kicker{font-size:12px;letter-spacing:.08em;text-transform:uppercase;font-weight:700;color:#198C51;margin:0 0 4px}
.abc-author-text .abc-author-name{font-size:24px;line-height:1.25;margin:0 0 6px;font-weight:700;font-family:Roboto,Arial,sans-serif}
.abc-author-text .abc-author-name a{color:#1E2633;text-decoration:none}
.abc-author-text .abc-author-name a:hover{color:#0446A4}
.abc-author-text .abc-credline{font-size:13px;line-height:1.5;color:#198C51;margin:0 0 16px}
.abc-credentials{background:#F5F5F5;border-radius:8px;padding:16px 20px;margin:4px 0 18px}
.abc-credentials strong{display:block;color:#1E2633;font-size:15px;margin-bottom:8px}
.abc-credentials ul{list-style:none;margin:0;padding:0}
.abc-credentials li{position:relative;padding-left:24px;margin:0 0 8px;font-size:14px;line-height:1.5}
.abc-credentials li:last-child{margin-bottom:0}
.abc-credentials li::before{content:"";position:absolute;left:2px;top:.45em;width:10px;height:10px;border-radius:50%;border:2.5px solid #0446A4}
.abc-author-links{display:flex;flex-wrap:wrap;gap:10px;margin:0!important}
.abc-author-links a{display:inline-block;font-size:14px;font-weight:500;text-decoration:none;border-radius:4px;padding:9px 16px;border:1.5px solid #0446A4;color:#0446A4}
.abc-author-links a:hover{background:#0446A4;color:#fff}
.abc-author-links a+a{background:#198C51;border-color:#198C51;color:#fff}
.abc-author-links a+a:hover{background:#13703F;border-color:#13703F}

/* Related articles */
.e-con.abc-related{--padding-top:48px;--padding-bottom:0;--padding-left:0;--padding-right:0;--gap:16px;--row-gap:16px;--column-gap:16px}
.abc-related-title .elementor-heading-title{font-size:28px;color:#1E2633;font-weight:700;margin:0;font-family:Roboto,Arial,sans-serif}
.abc-related-posts .elementor-post{border:1px solid #E3E6EB;border-radius:6px;overflow:hidden;background:#fff;transition:box-shadow .2s,transform .2s}
.abc-related-posts .elementor-post:hover{box-shadow:0 8px 24px rgba(30,38,51,.1);transform:translateY(-2px)}
.abc-related-posts .elementor-post__thumbnail__link{margin-bottom:0!important}
.abc-related-posts .elementor-post__text{padding:14px 16px 18px}
.abc-related-posts .elementor-post__title,.abc-related-posts .elementor-post__title a{font-size:16px;line-height:1.35;color:#1E2633;font-weight:700}

/* Mobile call / quote bar */
.e-con.abc-helpers{--padding-top:0;--padding-bottom:0;--padding-left:0;--padding-right:0;--min-height:0}
.abc-mobile-bar{display:none}

/* Tablet and below: stack layout, inline TOC */
@media (max-width:1024px){
  .abc-hero-img{width:100%}
  .e-con.abc-hero-text{--width:100%}
  .abc-hero-img img{aspect-ratio:16/9;max-height:none}
  .e-con.abc-hero{--gap:24px;--row-gap:24px;--column-gap:24px;--padding-top:32px;--padding-bottom:36px}
  .e-con.abc-article{max-width:none;width:100%}
  .e-con.abc-sidebar{--width:100%}
  .e-con.abc-sticky{position:static}
  .e-con.abc-body{--gap:36px;--row-gap:36px;--column-gap:36px;--padding-top:28px}
}
/* Phones */
@media (max-width:767px){
  .e-con.abc-hero,.e-con.abc-body{--padding-left:16px;--padding-right:16px}
  .e-con.abc-hero{--padding-top:24px;--padding-bottom:28px}
  .e-con.abc-author{--padding-left:20px;--padding-right:20px}
  /* tables become one card per row */
  .abc-content figure.wp-block-table{box-shadow:none;background:transparent;overflow:visible}
  .abc-content .wp-block-table table.abc-stack{min-width:0}
  .abc-content table.abc-stack,.abc-content table.abc-stack tbody{display:block}
  .abc-content table.abc-stack tr.abc-thead{display:none}
  .abc-content table.abc-stack tr{display:block;border-radius:10px;overflow:hidden;margin:0 0 12px;box-shadow:0 4px 16px rgba(30,38,51,.08);border:1px solid #E3E6EB}
  .abc-content .wp-block-table table.abc-stack td{display:grid;grid-template-columns:40% 1fr;gap:10px;padding:10px 14px;background:#fff!important;border-bottom:1px solid #E3E6EB}
  .abc-content .wp-block-table table.abc-stack td::before{content:attr(data-label);font-size:12px;font-weight:600;color:#5F6672;text-transform:uppercase;letter-spacing:.04em}
  .abc-content .wp-block-table table.abc-stack td:first-child{display:block;background:#0446A4!important;color:#fff!important}
  .abc-content .wp-block-table table.abc-stack td:first-child::before{display:none}
  .abc-content .wp-block-table table.abc-stack td:last-child{border-bottom:0}
  .abc-title .elementor-heading-title{font-size:30px}
  .abc-dek,.abc-dek p{font-size:16px}
  .abc-content{font-size:16px}
  .abc-content h2{font-size:23px}
  .abc-mobile-bar{display:grid;grid-template-columns:1fr 1fr;position:fixed;left:0;right:0;bottom:0;z-index:9998;box-shadow:0 -4px 16px rgba(0,0,0,.12)}
  .abc-mobile-bar a{padding:15px 10px;text-align:center;font-weight:700;text-decoration:none;color:#fff;font-size:15px;font-family:Roboto,Arial,sans-serif}
  .abc-mobile-bar a:first-child{background:#0446A4}
  .abc-mobile-bar a:last-child{background:#198C51}
  body.single-post{padding-bottom:52px}
}
